// coerceBoolOrComposite maps a flag value for a bool|object polymorphic
// field ("true"/"false" or JSON object) into the wire value the API expects.
// Empty input returns (nil, nil) so the caller can omit the field; any other
// non-boolean, non-JSON value is rejected instead of being sent as a bare
// string the API will 400 on.
func coerceBoolOrComposite(raw string) (any, error) {
	t := strings.TrimSpace(raw)
	if t == "" {
		return nil, nil
	}
	switch strings.ToLower(t) {
	case "true":
		return true, nil
	case "false":
		return false, nil
	}
	if looksLikeJSONComposite(t) {
		var v any
		if err := json.Unmarshal([]byte(t), &v); err != nil {
			return nil, fmt.Errorf("parsing JSON value: %w", err)
		}
		return v, nil
	}
	return nil, fmt.Errorf("expected true, false, or a JSON object, got %q", raw)
}

